import { normalize } from "./utils.js";
const escapeKey = (value) => value.replace(/[,= ]/g, (char) => `\\${char}`);
export const renderInfluxDb = (lines, now = new Date()) => {
    const timestamp = BigInt(Math.floor(now.getTime() / 1000)) * 1000000000n;
    return (lines
        .map(({ name, key, value }) => `${escapeKey(name)} ${escapeKey(normalize(key))}=${value} ${timestamp}`)
        .join("\n") + "\n");
};
